1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.function.common.Hashes;
6	import org.springframework.samples.petclinic.rest.function.common.Localities;
7	
8	/**
9	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where {@code REGION} is
10	 * the region code derived from the owner's postcode (see {@link Localities#ofPostcode(String)}) and
11	 * {@code HASH8} is the first 8 upper-case hex characters of SHA-256 over the owner's normalized
12	 * telephone concatenated with their last name (e.g. {@code NSW-1A2B3C4D}). There are no sequence
13	 * numbers: the code is a pure function of postcode, telephone and last name.
14	 *
15	 * <p>Wired after {@link NormalizeOwnerTelephone}, so the telephone read here is already in E.164 form
16	 * and every value derived from the customer code — the membership number and its check digit, the
17	 * create audit line and the read-model locality — reflects this region-and-hash identity.
18	 */
19	public class AssignOwnerCustomerCode {
20	
21	    /** Length of the hash segment: the first 8 upper-case hex characters of the SHA-256 digest. */
22	    private static final int HASH_LENGTH = 8;
23	
24	    public void service(@Val Owner owner) {
25	        String region = Localities.ofPostcode(owner.getPostcode());
26	        String hash8 = Hashes.sha256UpperHex(owner.getTelephone() + owner.getLastName(), HASH_LENGTH);
27	        owner.setCustomerCode(CustomerCode.format(region, hash8));
28	    }
29	}
