1	package org.springframework.samples.petclinic.rest.function.common;
2	
3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	/**
7	 * Fiscal-year arithmetic for the owner's date-derived values. The fiscal year starts on 1 July:
8	 * a date on or after 1 July belongs to the fiscal year identified by <em>that</em> calendar year,
9	 * and a date before 1 July belongs to the fiscal year identified by the <em>previous</em> calendar
10	 * year. So 1 Jul 2026 – 30 Jun 2027 is fiscal year 2026, labelled {@code FY26}.
11	 *
12	 * <p>The single definition of the fiscal-year basis, shared by the owner mapper: the {@code fiscalYear}
13	 * field ({@link #label}), the membership number's year segment ({@link #yy}) and the membership-points
14	 * tenure ({@link #between}) all derive from here so they cannot drift apart. Every input is the
15	 * business-day-adjusted {@code registrationDate}, so all three reflect the same effective date.
16	 */
17	public final class FiscalYear {
18	
19	    private FiscalYear() {
20	    }
21	
22	    /** The four-digit fiscal year the date falls in — the calendar year the 1 July year began. */
23	    public static int of(LocalDate date) {
24	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() : date.getYear() - 1;
25	    }
26	
27	    /** The two-digit fiscal year (e.g. {@code 26}), used as the membership number's year segment. */
28	    public static int yy(LocalDate date) {
29	        return of(date) % 100;
30	    }
31	
32	    /** The {@code FY<YY>} label for the date, e.g. {@code FY26} for any date in fiscal year 2026. */
33	    public static String label(LocalDate date) {
34	        return String.format("FY%02d", yy(date));
35	    }
36	
37	    /** Whole fiscal years elapsed from {@code start} to {@code end} (fiscal year of end minus of start). */
38	    public static long between(LocalDate start, LocalDate end) {
39	        return (long) of(end) - of(start);
40	    }
41	}
