1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.slf4j.Logger;
6	import org.slf4j.LoggerFactory;
7	
8	import tools.jackson.databind.ObjectMapper;
9	
10	import net.officefloor.plugin.variable.Val;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
13	
14	/**
15	 * Emits an audit line via the dedicated {@code AUDIT} logger on successful create, carrying
16	 * the persisted owner's id, {@code customerCode} and {@code registrationDate}, plus the derived
17	 * {@code membershipLevel} and {@code membershipNumber}. Wired after {@link SaveOwner} so the id is
18	 * assigned, and after the steps that set the customer code and business-day registration date, so
19	 * every value logged matches what {@code GET /owners/{id}} later returns.
20	 *
21	 * <p>The membership fields are derived, not stored. Rather than re-derive them here, this step reads
22	 * the {@link OwnerDto} published by {@link MapOwner}, the same DTO {@link RespondWithOwnerCreated}
23	 * sends, so the logged values and the response body cannot drift apart.
24	 *
25	 * <p>In addition to the human-readable line, it emits an immutable structured {@link OwnerCreatedEvent}
26	 * as a single JSON object, so audit consumers can parse creates without scraping text. The event's
27	 * identifier slot carries the owner's <strong>current primary identifier</strong> via
28	 * {@link Owner#primaryIdentifier()} — the customer code today, the memberId once that unification
29	 * lands — so the migration is a single edit at the domain level.
30	 */
31	public class AuditOwnerCreated {
32	
33	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
34	
35	    /** Monotonically increasing sequence across creates, stamped onto each structured event. */
36	    private static final AtomicLong SEQUENCE = new AtomicLong();
37	
38	    public void service(@Val Owner owner, @Val OwnerDto dto, ObjectMapper objectMapper) {
39	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} "
40	                + "membershipNumber={}",
41	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
42	                dto.getMembershipLevel(), dto.getMembershipNumber());
43	
44	        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQUENCE.incrementAndGet(), owner.getId(),
45	                owner.primaryIdentifier(), dto.getMembershipLevel());
46	        // Single-argument info(): the JSON braces are logged verbatim, not treated as SLF4J placeholders.
47	        AUDIT.info(objectMapper.writeValueAsString(event));
48	    }
49	}
