1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.rest.function.common.Hashes;
5	import org.springframework.samples.petclinic.rest.function.common.Soundex;
6	
7	/**
8	 * The single definition of an owner's {@code identityKey} — the one derived key that all duplicate
9	 * detection is expressed through. The key is the SHA-256 hex digest (64 lower-case hex characters) of
10	 * three normalized parts joined with {@code '|'}:
11	 *
12	 * <ol>
13	 * <li>the telephone in E.164 form (see {@link TelephoneNormalizer}),</li>
14	 * <li>the email lower-cased, or empty when absent (see {@link EmailNormalizer}), and</li>
15	 * <li>the Soundex of the last name (see {@link Soundex}), so surnames that sound alike collide.</li>
16	 * </ol>
17	 *
18	 * <p>A create is a duplicate — rejected with a 409 — only when its <em>whole</em> key equals an
19	 * existing owner's. Because the telephone is part of the key, two owners with the same last name (and
20	 * postcode) but different telephones have different keys and are both allowed — the second is created
21	 * as a soft match (see {@link AssignOwnerPossibleDuplicate}), not rejected.
22	 *
23	 * <p>Shared by {@link RequireUniqueIdentity} (which rejects a collision) and the owner mapper (which
24	 * returns the key), so both compute it the same way and cannot drift apart. Public because the mapper
25	 * lives in another package.
26	 */
27	public final class IdentityKey {
28	
29	    /** The identity key for the given (raw) telephone, email and last name. */
30	    public static String of(String telephone, String email, String lastName) {
31	        String tel = TelephoneNormalizer.toE164(telephone);
32	        if (tel == null) {
33	            tel = telephone == null ? "" : telephone;
34	        }
35	        String em = EmailNormalizer.isBlank(email) ? "" : EmailNormalizer.normalize(email);
36	        String snd = Soundex.of(lastName);
37	        return Hashes.sha256Hex(tel + "|" + em + "|" + snd);
38	    }
39	
40	    /** The identity key of an existing (persisted) owner. */
41	    public static String ofOwner(Owner owner) {
42	        return of(owner.getTelephone(), owner.getEmail(), owner.getLastName());
43	    }
44	
45	    private IdentityKey() {
46	    }
47	}
48

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.rest.function.common.Hashes;
5	
6	/**
7	 * The single definition of an owner's {@code householdId}: a deterministic identifier derived from
8	 * the owner's last name and postcode, so owners with the same last name and postcode share it
9	 * automatically. The value is the first 12 hex characters of SHA-256 over
10	 * {@code normalizedLastName + '|' + postcode}, where the last name is compared case-insensitively
11	 * after collapsing runs of whitespace.
12	 *
13	 * <p>Because it is a pure function of {@code (lastName, postcode)}, every owner computes its own id
14	 * independently and members of one household always agree — there is nothing to link or backfill.
15	 * Shared by {@link AssignHousehold} (which stamps it onto the new owner) and {@link OwnerHousehold}
16	 * (which counts household members and caps membershipLevel), so every place that keys off the household
17	 * applies the one rule and they cannot drift apart. Duplicate detection and the soft match no longer
18	 * key off the household id — they use the {@link IdentityKey} and {@link Soundex} of the last name.
19	 *
20	 * <p>Kept out of the function classes themselves because OfficeFloor requires each function class to
21	 * expose exactly one public method.
22	 */
23	final class HouseholdKey {
24	
25	    /** Length of the household id: the first 12 hex characters of the SHA-256 digest. */
26	    private static final int ID_LENGTH = 12;
27	
28	    private HouseholdKey() {
29	    }
30	
31	    /**
32	     * The deterministic {@code householdId} for the given last name and postcode: the first 12 hex
33	     * characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. A {@code null} postcode
34	     * is treated as the empty string.
35	     */
36	    static String householdId(String lastName, String postcode) {
37	        String key = normalize(lastName) + "|" + (postcode == null ? "" : postcode);
38	        return Hashes.sha256Hex(key).substring(0, ID_LENGTH);
39	    }
40	
41	    /**
42	     * The deterministic {@code householdId} of the given owner — the single home of "which two fields
43	     * make a household", mirroring {@link IdentityKey#ofOwner}, so callers never re-pluck the tuple.
44	     */
45	    static String householdId(Owner owner) {
46	        return householdId(owner.getLastName(), owner.getPostcode());
47	    }
48	
49	    /** Lower-cases and collapses runs of whitespace to a single space for case- and
50	     *  whitespace-insensitive comparison. */
51	    private static String normalize(String value) {
52	        if (value == null) {
53	            return "";
54	        }
55	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
56	    }
57	}
