1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * The duplicate block of the create-owner pipeline: rejects the request with a 409 (via
11	 * {@code DuplicateIdentityExceptionHandler}) on an <b>identity duplicate</b> — an exact match on the
12	 * whole {@link IdentityKey} (the SHA-256 of {@code telephone|email|soundex(lastName)}) — because that
13	 * is the same person. This single identity key is now the only duplicate rule: there is no separate
14	 * household-duplicate 409 keyed off the computed {@link HouseholdKey#householdId}.
15	 *
16	 * <p>Sharing a last name and postcode is <em>not</em> in itself a duplicate: two owners with the same
17	 * last name and postcode but different telephones have different identity keys and are both allowed —
18	 * the second is created and flagged as a soft match by {@link AssignOwnerPossibleDuplicate}. A new
19	 * member's membershipLevel is then capped relative to the existing members by {@link OwnerHousehold};
20	 * it is no longer necessary to declare {@code sharesHousehold}.
21	 *
22	 * <p>Runs after {@link NormalizeOwnerTelephone} and {@link NormalizeOwnerEmail}, so the candidate's
23	 * telephone and email are already normalized, and after {@link RequireEmailNotDisposable} so the
24	 * email-domain blocklist is applied first. The new owner is not persisted yet, so every match found is
25	 * another owner.
26	 */
27	public class RequireUniqueIdentity {
28	
29	    public void service(@Val OwnerFieldsDto owner, OwnerRepository ownerRepository)
30	            throws DuplicateIdentityException {
31	        String candidate = IdentityKey.of(owner.getTelephone(), owner.getEmail(), owner.getLastName());
32	        for (Owner existing : ownerRepository.findAll()) {
33	            if (!DuplicateCandidates.isCandidate(existing)) {
34	                continue; // a soft-deleted owner no longer blocks a duplicate or identity match
35	            }
36	            if (candidate.equals(IdentityKey.ofOwner(existing))) {
37	                throw new DuplicateIdentityException(candidate);
38	            }
39	        }
40	    }
41	}
42

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.rest.function.common.FiscalYear;
7	
8	/**
9	 * The single definition of the membership points → level formula, so every place that needs an owner's
10	 * level computes it the same way and they cannot drift apart. The household size is not read off the
11	 * owner here but passed in explicitly ({@code null} for an unknown/single-member household): it depends
12	 * on other owners and is computed once by {@link OwnerHousehold}, and taking it as an argument keeps
13	 * this a pure function with no hidden reads or writes.
14	 *
15	 * <p>Shared by {@code OwnerMapper} (which exposes {@code membershipPoints} and the capped
16	 * {@code membershipLevel} on the DTO) and {@link OwnerHousehold} (which reads each other household
17	 * member's <em>raw</em> level to compute the ceiling). Kept out of the function classes because
18	 * OfficeFloor requires each function class to expose exactly one public method.
19	 */
20	public final class MembershipLevel {
21	
22	    private MembershipLevel() {
23	    }
24	
25	    /**
26	     * The owner's membership points. Starting from 0: add 2 when an email address is present, add 1
27	     * when the owner has no namesakes ({@code namesakeCount} is 0), add 2 for a household of 3 or more
28	     * members, and add 3 when the owner's tenure exceeds one fiscal year (more than one elapsed fiscal
29	     * year since the {@code registrationDate}; the fiscal year starts on 1 July).
30	     */
31	    public static int points(Owner owner, Integer householdSize) {
32	        int points = 0;
33	        if (hasEmail(owner)) {
34	            points += 2;
35	        }
36	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
37	            points += 1;
38	        }
39	        if (householdSize != null && householdSize >= 3) {
40	            points += 2;
41	        }
42	        long tenureFiscalYears = owner.getRegistrationDate() == null ? 0
43	                : FiscalYear.between(owner.getRegistrationDate(), LocalDate.now());
44	        if (tenureFiscalYears > 1) {
45	            points += 3;
46	        }
47	        return points;
48	    }
49	
50	    /**
51	     * The raw numeric level for a points total: level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for
52	     * 6 or more. This is the level before any household ceiling is applied.
53	     */
54	    public static int level(int points) {
55	        if (points <= 1) {
56	            return 1;
57	        }
58	        if (points <= 3) {
59	            return 2;
60	        }
61	        if (points <= 5) {
62	            return 3;
63	        }
64	        return 4;
65	    }
66	
67	    /** Whether the owner has a usable email address. */
68	    public static boolean hasEmail(Owner owner) {
69	        return owner.getEmail() != null && !owner.getEmail().isBlank();
70	    }
71	}
