9	/**
10	 * Stamps the owner's household size via {@link OwnerHousehold} and maps it to its {@link OwnerDto}
11	 * once, publishing the DTO for downstream steps. Both {@link AuditOwnerCreated} and
12	 * {@link RespondWithOwnerCreated} read the published DTO rather than re-deriving it, so the audit
13	 * line and the response body are guaranteed to agree and the derivation lives in a single place.
14	 */
15	public class MapOwner {
16	
17	    public void service(@Val Owner owner, OwnerHousehold ownerHousehold, OwnerMapper ownerMapper,
18	            Out<OwnerDto> dtoOut) {
19	        dtoOut.set(ownerMapper.toOwnerDto(ownerHousehold.stamp(owner)));
20	    }
21	}
