12	 * {@link AssignOwnerCustomerCode} is a pure function of postcode, telephone and last name, so two
13	 * distinct owners can in principle compute the same code. When the computed code already belongs to
14	 * an existing owner, this step appends {@code -<n>} with the smallest {@code n} of 2 or more that
15	 * makes it unique (e.g. {@code NSW-1A2B3C4D} → {@code NSW-1A2B3C4D-2}), guaranteeing distinct owners
16	 * always receive distinct customer codes.
17	 *
18	 * <p>Wired after {@link AssignOwnerCustomerCode} and before the create is saved, so the existing
19	 * owners read here never include this owner.
20	 */
21	public class DeduplicateOwnerCustomerCode {
22	
23	    /** The smallest suffix appended on a collision. */
24	    private static final int FIRST_SUFFIX = 2;
25	
26	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
27	        String base = owner.getCustomerCode();
28	        Set<String> existing = ownerRepository.findAll().stream()
29	                .map(Owner::getCustomerCode)
30	                .collect(Collectors.toSet());
31	        if (!existing.contains(base)) {
32	            return;
33	        }
34	        String unique;
35	        for (int n = FIRST_SUFFIX; existing.contains(unique = CustomerCode.withSuffix(base, n)); n++) {
36	            // advance to the next suffix until the code is unique
37	        }
38	        owner.setCustomerCode(unique);
39	    }
40	}
