package org.springframework.samples.petclinic.rest.function.common;

/**
 * Computes a single Luhn check digit over the digits contained in a string. Used to derive an
 * owner's {@code checkDigit} from their customerCode. The algorithm is the standard Luhn
 * (right-to-left doubling of alternate digits); non-digit characters are ignored, so separators
 * such as the '-' in a customerCode do not affect the result. Pinned so both the Spring and
 * OfficeFloor arms produce identical values.
 */
public final class Luhn {

    private Luhn() {
    }

    /** The Luhn check digit (0-9) over the digits contained in {@code s}; non-digits are ignored. */
    public static int checkDigit(String s) {
        int sum = 0;
        boolean dbl = true;
        for (int i = s.length() - 1; i >= 0; i--) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }
}

package org.springframework.samples.petclinic.rest.function.common;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

/**
 * SHA-256 helper used to derive an owner's {@code customerCode} hash segment. Pinned so both the
 * Spring and OfficeFloor arms produce identical values: the digest is taken over the UTF-8 bytes and
 * rendered as lower-case hex, from which callers take the leading, upper-cased characters.
 *
 * <p>Kept out of the function classes themselves because OfficeFloor requires each function class to
 * expose exactly one public method.
 */
public final class Hashes {

    private Hashes() {
    }

    /** The full lower-case hex SHA-256 of the UTF-8 bytes of {@code s}. */
    public static String sha256Hex(String s) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(s.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }

    /** The first {@code n} upper-case hex characters of SHA-256 over {@code s}. */
    public static String sha256UpperHex(String s, int n) {
        return sha256Hex(s).substring(0, n).toUpperCase(Locale.ROOT);
    }
}

package org.springframework.samples.petclinic.rest.function.common;

import java.time.LocalDate;
import java.time.Month;

/**
 * Fiscal-year arithmetic for the owner's date-derived values. The fiscal year starts on 1 July:
 * a date on or after 1 July belongs to the fiscal year identified by <em>that</em> calendar year,
 * and a date before 1 July belongs to the fiscal year identified by the <em>previous</em> calendar
 * year. So 1 Jul 2026 – 30 Jun 2027 is fiscal year 2026, labelled {@code FY26}.
 *
 * <p>The single definition of the fiscal-year basis, shared by the owner mapper: the {@code fiscalYear}
 * field ({@link #label}), the membership number's year segment ({@link #yy}) and the membership-points
 * tenure ({@link #between}) all derive from here so they cannot drift apart. Every input is the
 * business-day-adjusted {@code registrationDate}, so all three reflect the same effective date.
 */
public final class FiscalYear {

    private FiscalYear() {
    }

    /** The four-digit fiscal year the date falls in — the calendar year the 1 July year began. */
    public static int of(LocalDate date) {
        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() : date.getYear() - 1;
    }

    /** The two-digit fiscal year (e.g. {@code 26}), used as the membership number's year segment. */
    public static int yy(LocalDate date) {
        return of(date) % 100;
    }

    /** The {@code FY<YY>} label for the date, e.g. {@code FY26} for any date in fiscal year 2026. */
    public static String label(LocalDate date) {
        return String.format("FY%02d", yy(date));
    }

    /** Whole fiscal years elapsed from {@code start} to {@code end} (fiscal year of end minus of start). */
    public static long between(LocalDate start, LocalDate end) {
        return (long) of(end) - of(start);
    }
}

